L["Reload to finish importing."] = "가져오기를 마치려면 다시 불러오세요."
L["Cannot reload during combat. Type /reload instead."] = "전투 중에는 다시 불러올 수 없습니다. 대신 /reload 를 입력하세요."
L["Flat, clean and modern. The look EllesmereUI was designed around."] = "평평하고 깔끔한 현대적 모양. EllesmereUI가 처음부터 맞춰 만든 모습입니다."
L["Blizzard's own frame and button art, with EllesmereUI's features."] = "블리자드 기본 프레임과 버튼 그림에 EllesmereUI 기능을 더한 모양입니다."
L["The original frames, rings and slots where the game has them, with EllesmereUI's features."] = "게임에 있는 원래 프레임, 고리, 칸 그림에 EllesmereUI 기능을 더한 모양입니다."
L["Style changed for this profile. A UI reload is needed to apply it."] = "이 프로필의 스타일이 바뀌었습니다. 적용하려면 UI를 다시 불러와야 합니다."
L["Same setup, same EllesmereUI features, a new look: switch to Blizzard Style or the new Classic WoW UI in one click, and switch back any time."] = "설정도 EllesmereUI 기능도 그대로, 모양만 새롭게: 한 번 클릭으로 블리자드 스타일이나 새 클래식 WoW UI로 바꾸고, 언제든 되돌릴 수 있습니다."
L["Global Settings > Style sets the look for the whole UI or for each module."] = "전체 설정 > 모양에서 UI 전체 또는 모듈별 모양을 정합니다."
L["Settings Overrides are the most powerful system in EllesmereUI, and the deepest. A few minutes with this video will save you hours of working it out on your own."] = "설정 재정의는 EllesmereUI에서 가장 강력하고 가장 깊은 기능입니다. 이 영상을 몇 분만 보면 혼자 알아내느라 쓸 몇 시간을 아낄 수 있습니다."
L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "재정의가 있는 설정의 기본값을 바꿨습니다. 재정의는 자기 값을 따로 가지므로, 이 변경은 재정의가 적용되는 전문화나 조건에는 반영되지 않습니다. 재정의 쪽도 바꾸려면 모듈 검색창 옆의 직업 문양에서 그 재정의를 골라 거기서 고치세요."
L["Gold border settings have overrides. Hover info icon for details."] = "금색 테두리 설정에는 재정의가 있습니다. 자세한 내용은 정보 아이콘에 마우스를 올리세요."
L["Popular presets now live on the new EllesmereUI website including full previews, step-by-step install instructions, plus new presets added every day!"] = "인기 프리셋은 이제 새 EllesmereUI 웹사이트에 있습니다. 전체 미리보기와 단계별 설치 방법을 볼 수 있고, 새 프리셋이 매일 추가됩니다!"
L["Each preset's page includes its import string."] = "프리셋마다 페이지에 가져오기 문자열이 있습니다."
L["This profile string does not carry any global settings."] = "이 프로필 문자열에는 전체 설정이 들어 있지 않습니다."
L["Apply the sharer's fonts, custom colours, dark mode, accent colour and UI scale. Off = keep your own global look and scale; only the selected modules' settings come in."] = "공유한 사람의 글꼴, 사용자 지정 색상, 어두운 모드, 강조 색상, UI 크기를 적용합니다. 끄면 내 전체 모양과 크기를 유지하고, 고른 모듈의 설정만 가져옵니다."
L["Reload to finish switching to the new profile."] = "새 프로필로 전환을 마치려면 다시 불러오세요."
L[" Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = " 이 요소는 여기서 마우스오버도 막혀 있습니다: 마우스를 올렸을 때의 동작이 공용 설정을 따르므로, 재정의로는 표시 상태로만 둘 수 있습니다."
L["This element cannot use group-based visibility."] = "이 요소는 그룹 기준 표시 조건을 쓸 수 없습니다."
L["Requires a client with gliding events."] = "활공 이벤트가 있는 클라이언트가 필요합니다."
L["Not available while a legacy visibility value is selected. Pick Never or Always first."] = "예전 표시 여부 값이 선택되어 있으면 쓸 수 없습니다. 먼저 안 함이나 항상을 고르세요."
L["Scales the text size of Blizzard tooltips."] = "블리자드 툴팁의 글자 크기를 조절합니다."
L["Sizes the movement alert's free text, bar number and icon countdown. Switching the alert's Display Mode re-seeds this value."] = "이동 알림의 자유 글자, 바 숫자, 아이콘 카운트다운 크기입니다. 알림의 표시 방식을 바꾸면 이 값이 다시 정해집니다."
L["%1$s is active: the tracker keeps Blizzard's own text."] = "%1$s 사용 중: 추적기는 블리자드 기본 글자를 유지합니다."
L["Blizzard's rounded button art, or the classic square slots, with every EllesmereUI bar feature."] = "블리자드의 둥근 버튼 그림 또는 클래식 네모 칸에 EllesmereUI 단축바 기능을 모두 더합니다."
L["Blizzard's frame art, portraits and bar shapes, or the classic frames, with every EllesmereUI frame feature."] = "블리자드의 프레임 그림, 초상화, 바 모양 또는 클래식 프레임에 EllesmereUI 프레임 기능을 모두 더합니다."
L["Blizzard's health and cast bar art, or the classic flat plates, with every EllesmereUI nameplate feature."] = "블리자드의 생명력 바와 시전 바 그림 또는 클래식 평면 이름표에 EllesmereUI 이름표 기능을 모두 더합니다."
L["Blizzard's rounded cooldown icons, or the classic square slots, with every EllesmereUI icon feature."] = "블리자드의 둥근 재사용 대기시간 아이콘 또는 클래식 네모 칸에 EllesmereUI 아이콘 기능을 모두 더합니다."
L["Blizzard's buff bar art, or the classic cast bar frame, with every EllesmereUI tracked bar feature."] = "블리자드의 강화 효과 바 그림 또는 클래식 시전 바 틀에 EllesmereUI 추적 바 기능을 모두 더합니다."
L["Blizzard's cast bar art, or the classic cast bar frame, with every EllesmereUI cast bar feature."] = "블리자드의 시전 바 그림 또는 클래식 시전 바 틀에 EllesmereUI 시전 바 기능을 모두 더합니다."
L["The personal resource display's bar frame, or the classic cast bar frame, on the health, power and class resource bars, with every EllesmereUI bar feature."] = "생명력, 자원, 직업 자원 바에 개인 자원 표시의 바 틀 또는 클래식 시전 바 틀을 쓰고, EllesmereUI 바 기능을 모두 더합니다."
L["Blizzard's round minimap and header, or the classic ring, with every EllesmereUI minimap feature."] = "블리자드의 둥근 미니맵과 머리 부분 또는 클래식 고리에 EllesmereUI 미니맵 기능을 모두 더합니다."
L["Blizzard's meter window and bar art, or a window in the classic chat tabs' border, with every EllesmereUI meter feature."] = "블리자드의 미터기 창과 바 그림 또는 클래식 대화 탭 테두리를 두른 창에 EllesmereUI 미터기 기능을 모두 더합니다."
L["Blizzard's own tracker, with every EllesmereUI tracker feature. Both stock styles look the same here."] = "블리자드 기본 추적기에 EllesmereUI 추적기 기능을 모두 더합니다. 여기서는 두 기본 스타일이 똑같이 보입니다."
L["Blizzard's own chat window, tabs and input box, or the same window with the classic tab art, with every EllesmereUI chat feature."] = "블리자드 기본 대화창, 탭, 입력창 또는 같은 창에 클래식 탭 그림을 쓰고, EllesmereUI 대화 기능을 모두 더합니다."
L["Blizzard's raid frame edge and highlights, or the classic ones, with every EllesmereUI raid frame feature."] = "블리자드 공격대 프레임 테두리와 강조 또는 클래식 모양에 EllesmereUI 공격대 프레임 기능을 모두 더합니다."
L["Blizzard's own character sheet with the EllesmereUI stats, slot text and socket panel added; the Calc tab stays with the EllesmereUI look."] = "블리자드 기본 캐릭터 창에 EllesmereUI 능력치, 칸 글자, 보석 창을 더합니다. 계산 탭은 EllesmereUI 모양을 유지합니다."
L["Blizzard's own friends window and cards, with the EllesmereUI class icons, class-coloured names and region icons added. Both stock styles look the same here."] = "블리자드 기본 친구 창과 카드에 EllesmereUI 직업 아이콘, 직업 색상 이름, 지역 아이콘을 더합니다. 여기서는 두 기본 스타일이 똑같이 보입니다."
L["Size of the Classic frame around the bar."] = "바를 두르는 클래식 틀의 크기입니다."
L["%1$s is active. Settings that only apply to the EllesmereUI look are hidden."] = "%1$s 사용 중입니다. EllesmereUI 모양에만 적용되는 설정은 숨깁니다."
L["Changing the style requires a UI reload to apply."] = "모양을 바꾸면 UI를 다시 불러와야 적용됩니다."
L["Your setup and every EllesmereUI feature carry over; only the look changes. Apply a style to every module in one click, or set each module below. Changing a style reloads the UI."] = "설정과 EllesmereUI 기능은 모두 그대로, 모양만 바뀝니다. 한 번 클릭으로 모든 모듈에 적용하거나, 아래에서 모듈마다 정하세요. 모양을 바꾸면 UI를 다시 불러옵니다."
L["Texture for every unit frame cast bar. Inherit follows each unit's bar texture."] = "모든 유닛 프레임 시전 바의 텍스처입니다. 따르기는 유닛마다의 바 텍스처를 따릅니다."
L["Texture for the class resource bar."] = "직업 자원 바의 텍스처입니다."
L["Texture for the health, power and class resource bars."] = "생명력, 자원, 직업 자원 바의 텍스처입니다."
L["%1$s is active: chat keeps Blizzard's own background and tab art."] = "%1$s 사용 중: 대화창은 블리자드 기본 배경과 탭 그림을 유지합니다."
L["Used by the movement alert's Bar display mode."] = "이동 알림의 바 표시 방식에서 씁니다."
L["*Blizzard's auto targeting (soft target) setting can cause brief flickering when your actual target dies but a soft-target is still active."] = "*블리자드의 자동 대상 지정(소프트 타겟) 설정은 실제 대상이 죽었지만 소프트 타겟이 아직 활성일 때 잠깐 깜빡임을 유발할 수 있습니다."
L["Addon not loaded"] = "애드온이 로드되지 않음"
L["Anchor to Cursor"] = "커서에 고정"
L["at least one Celebration Trigger"] = "축하 트리거 중 하나 이상"
L["Background opacity for Dark Mode bars. Applies to Unit Frames and Raid Frames only (Resource Bars ignore it)."] = "어두운 모드 바의 배경 불투명도입니다. 유닛 프레임과 공격대 프레임에만 적용됩니다 (자원 바에는 적용되지 않음)."
L["Blackens every class colour by this amount, everywhere class colours are used."] = "직업 색상이 사용되는 모든 곳에서 직업 색상을 이 수치만큼 어둡게 만듭니다."
L["Blackens every class-resource colour by this amount, everywhere class-resource colours are used."] = "직업 보조 자원 색상이 사용되는 모든 곳에서 해당 색상을 이 수치만큼 어둡게 만듭니다."
L["Blackens every power colour by this amount, everywhere power colours are used."] = "자원 색상이 사용되는 모든 곳에서 자원 색상을 이 수치만큼 어둡게 만듭니다."
L["Blackens power-colored Power Bar backgrounds (Unit Frames and Raid Frames) by this amount, on top of Power Color Darken."] = "자원 색상으로 칠해진 자원 바 배경(유닛 프레임 및 공격대 프레임)을 자원 색상 어둡게에 더해 이 수치만큼 검게 만듭니다."
L["Choose which addons to import. Any addons not included will use your active profile's settings in the new profile."] = "가져올 애드온을 선택하세요. 포함되지 않은 애드온은 새 프로필에서 활성 프로필의 설정을 사용합니다."
L["Choose which addons you want enabled. You can change any of these later in the EllesmereUI settings panel."] = "사용할 애드온을 선택하세요. 나중에 EllesmereUI 설정 패널에서 변경할 수 있습니다."
L["Coming soon"] = "곧 추가 예정"
L["Configure alerts for missing Beacon of Light or Faith."] = "빛의 봉화 또는 신앙의 봉화 누락 알림을 설정합니다."
L["Controls the text rendering style used across all UI elements"] = "모든 UI 요소에 사용되는 글자 렌더링 모양을 제어합니다"
L["Disable "] = "비활성화 "
L["Discord"] = "디스코드"
L["Enable "] = "활성화 "
L["Enable/disable any time via the options panel sidebar."] = "설정 패널 사이드바에서 언제든지 활성/비활성화할 수 있습니다."
L["Enables sharpening to improve image clarity. Especially noticeable at lower render scales."] = "선명도를 높여 화면 선명도를 개선합니다. 낮은 렌더 배율에서 특히 눈에 띕니다."
L["Fill opacity for Dark Mode bars. Applies to Unit Frames and Raid Frames only (Resource Bars ignore it)."] = "어두운 모드 바의 채우기 불투명도입니다. 유닛 프레임과 공격대 프레임에만 적용됩니다 (자원 바에는 적용되지 않음)."
L["Havoc"] = "파멸"
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "게임 ESC/일시 정지 메뉴에서 EllesmereUI 버튼을 숨깁니다."
L["Hides the sync icons on the sidebar module list."] = "사이드바 추가기능 목록의 동기화 아이콘을 숨깁니다."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "게임 ESC/일시 정지 메뉴에서 잠금 해제 모드 버튼을 숨깁니다. EUI 설정 패널에서는 여전히 잠금 해제 모드를 전환할 수 있습니다."
L["Import the anchor & size-match relationships from this profile. Off = keep your own layout; only the selected modules' own positions/settings come in."] = "이 프로필의 앵커 및 크기 일치 관계를 가져옵니다. 끄면 현재 레이아웃을 유지하고 선택한 추가기능의 자체 위치/설정만 적용됩니다."
L["In Maintenance"] = "점검 중"
L["Include the anchor & size-match relationships between modules. Off = export each module's own positions only, with no cross-module tying."] = "추가기능 간 앵커 및 크기 일치 관계를 포함합니다. 끄면 각 추가기능의 자체 위치만 내보내고 추가기능 간 연결은 제외됩니다."
L["Keybinds respond on key down instead of key up. This helps make your abilities feel more responsive."] = "키를 뗄 때가 아니라 누를 때 단축키가 반응합니다. 기술 반응성을 높이는 데 도움이 됩니다."
L["Never miss an update again. The new Patch Notes section breaks down what's new each release, with quick links straight to every new setting."] = "이제 업데이트를 놓치지 마세요. 새 패치 노트 섹션이 매 릴리스의 변경점을 정리하고, 새 설정으로 바로 가는 링크를 제공합니다."
L["No conditional overrides yet. Click the Conditional Overrides button next to the module search bar and create a conditional group (Dungeon, Raid, Keybind...). Spec overrides always take precedence over conditionals."] = "아직 조건부 재정의가 없습니다. 추가기능 검색창 옆의 조건부 재정의 버튼을 눌러 조건 그룹(던전, 공격대, 단축키...)을 만드세요. 전문화 재정의는 항상 조건부보다 우선합니다."
L["No other profiles to sync to"] = "동기화할 다른 프로필이 없습니다"
L["No Profile Level Customizations"] = "프로필 수준의 사용자 지정 없음"
L["On (default): one profile's palette is shared across every profile (chosen via Pull Colors From). Off: each profile keeps its own custom colors (Power, Class Resource, Class, Resource)."] = "켜짐 (기본): 한 프로필의 색상표가 모든 프로필에 공유됩니다 (색상 가져올 프로필에서 선택). 꺼짐: 각 프로필이 자체 사용자 지정 색상을 유지합니다 (자원, 직업 자원, 직업, 직업별 자원)."
L["Optimizes your graphics settings for maximum FPS and visual clarity."] = "최대 FPS와 시각적 선명도를 위해 그래픽 설정을 최적화합니다."
L["Patreon"] = "패트리온"
L["PayPal"] = "페이팔"
L["Pet Move"] = "소환수 이동"
L["Prevents Blizzard from dimming Swiftmend on action bars and CDM based on Efflorescence state."] = "꽃피움 상태에 따라 블리자드가 행동 단축바와 CDM에서 신속한 치유를 흐리게 하는 것을 방지합니다."
L["Reset to default"] = "기본값으로 초기화"
L["Set UI Scale to 0.5333"] = "UI 크기를 0.5333으로 설정"
L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "모든 EllesmereUI 요소(탭, 반짝임, 강조, 테두리)에 사용되는 강조 색상을 설정합니다. 기본값은 테마 색상입니다."
L["Sets the scale of the entire game UI. Lower values make everything smaller, higher values make everything larger."] = "전체 게임 UI의 크기를 설정합니다. 값이 낮을수록 작아지고, 높을수록 커집니다."
L["Sets the UI scale to the exact pixel-perfect value used by other addons. EllesmereUI does not require this to be pixel perfect."] = "UI 배율을 다른 애드온이 쓰는 정확한 픽셀-퍼펙트 값으로 설정합니다. EllesmereUI 는 픽셀-퍼펙트가 필수는 아닙니다."
L["Shift + right click to hide video guide icons"] = "Shift + 우클릭으로 영상 가이드 아이콘 숨김"
L["Show a pulsing dot on the Patch Notes button whenever EllesmereUI updates to a new version."] = "EllesmereUI가 새 버전으로 업데이트될 때마다 패치 노트 버튼에 깜빡이는 점을 표시합니다."
L["Show Combat Damage Text"] = "전투 피해 글자 표시"
L["Show one-time video guide badges next to new or complex features. Each badge disappears forever once clicked."] = "새롭거나 복잡한 기능 옆에 일회성 영상 가이드 배지를 표시합니다. 각 배지는 한 번 클릭하면 영구히 사라집니다."
L["Slug outline renders higher quality outlines compared to the base WoW outline mode but may make outline effects appear slightly thicker."] = "Slug 외곽선은 기본 와우(WoW) 외곽선 모드에 비해 더 높은 품질의 외곽선을 표현하지만, 외곽선 효과가 약간 더 두껍게 보일 수 있습니다."
L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "어두운 모드 바 뒤에 표시되는 배경 색상입니다 (유닛 프레임, 공격대 프레임, 자원 바)."
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "재사용 대기시간 관리자는 단순히 대기시간만 보여주는 게 아니라 주문별 설정, 바 반짝임, 추적 바 등 훨씬 많은 기능이 있습니다! 더 잘 활용하는 팁과 요령을 확인해보세요."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "EllesmereUI 설정 창의 표시 언어입니다. \"자동\"은 게임 클라이언트를 따릅니다. 번역되지 않은 글자는 영문으로 표시됩니다."
L["the Randomly trigger"] = "무작위 발동"
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "이 설정은 주변 배경 디테일보다 프레임(FPS)과 화면 선명도를 우선시합니다. 텍스처는 고품질로 유지되기 때문에 캐릭터와 그래픽은 여전히 깔끔하게 보입니다."
L["This bar will only show if you have an enemy targeted"] = "적을 대상으로 했을 때만 이 바가 표시됩니다"
L["This element doesn't support both Height and Width matching"] = "이 요소는 높이와 너비 일치를 동시에 지원하지 않습니다"
L["This feature requires Snap Elements to be enabled"] = "이 기능은 요소 맞춤이 활성화되어 있어야 합니다"
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "주문 예약 창(Spell Queue Window)입니다. 한 번에 너무 많은 주문이 예약돼 게임이 버벅이는 걸 방지합니다. 권장값은 보통 최소 200 + 본인의 핑입니다. 정확한 동작을 잘 모르겠으면 400으로 두세요."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "여기에서 잠금 해제 모드의 설정을 제어할 수 있습니다.\n\n드래그 또는 방향키(+쉬프트)로 요소 위치 변경\n어떤 요소든 고정, 높이 일치, 너비 일치 가능.\n맞춤은 가장 가까운 요소 기준이며, 우클릭 또는 설정\n아이콘으로 특정 요소에만 맞출 수 있습니다."
L["This module can't be overridden. Exit the override editing session to open it."] = "이 추가기능은 재정의할 수 없습니다. 열려면 재정의 편집 세션을 종료하세요."
L["This option is only available for the Custom Color Theme"] = "이 설정은 사용자 지정 색상 테마에서만 사용할 수 있습니다"
L["This resets every EUI addon, not just the current one."] = "현재 애드온만이 아니라 모든 EUI 애드온이 초기화됩니다."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "이 유닛은 블리자드 기본 프레임을 사용합니다 -- 여기서 설정할 EllesmereUI 옵션이 없습니다."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "이 유닛의 프레임이 숨겨져 있습니다 -- 여기서 설정할 EllesmereUI 옵션이 없습니다."
L["This will not reset addon-specific Quick Setup."] = "애드온별 빠른 설정은 초기화되지 않습니다."
L["Toggle EllesmereUI's optional buttons: the Escape menu buttons and the minimap button."] = "EllesmereUI의 선택 버튼(Esc 메뉴 버튼과 미니맵 버튼)을 켜고 끕니다."
L["Track consumables and raid buffs for instanced content."] = "인스턴스 콘텐츠의 소모품과 공격대 강화 효과를 추적합니다."
L["Turns Dark Mode on or off for the class resource bar."] = "직업 자원 바의 어두운 모드를 켜거나 끕니다."
L["Turns Dark Mode on or off for Unit Frames and Raid Frames at once."] = "유닛 프레임과 공격대 프레임의 어두운 모드를 한 번에 켜거나 끕니다."
L["Twitch"] = "트위치"
L["Unlock Mode is how you move and resize everything in EllesmereUI, and it is packed with tools: anchors, width matching, fallback anchors, per-group layouts. This video gets you fluent fast."] = "잠금 해제 모드는 EllesmereUI의 모든 요소를 이동하고 크기 조정하는 방법이며, 기준점, 너비 맞춤, 대체 기준점, 그룹별 배치 등 다양한 도구를 갖추고 있습니다. 이 영상으로 빠르게 익힐 수 있습니다."
L["WARNING: This feature requires you to re-log or restart WoW to take effect."] = "경고: 이 기능을 적용하려면 재접속하거나 WoW를 다시 시작해야 합니다."
L["You changed settings while profile sync is active. Please reload your UI for sync changes to take effect."] = "프로필 동기화가 켜진 상태에서 설정을 변경했습니다. 변경 사항을 적용하려면 UI를 다시 로드하세요."
L["Your current spec has an assigned profile so you cannot switch to another. Please unassign to switch."] = "현재 전문화에 할당된 프로필이 있어 다른 프로필로 전환할 수 없습니다. 전환하려면 먼저 할당을 해제하세요."
L["|cff0cd29dLeft-click:|r |cffE0E0E0Toggle EllesmereUI|r"] = "|cff0cd29d좌클릭:|r |cffE0E0E0EllesmereUI 켜기/끄기|r"
L["|cff0cd29dMiddle-click:|r |cffE0E0E0Hide Minimap Button|r"] = "|cff0cd29d휠클릭:|r |cffE0E0E0미니맵 버튼 숨기기|r"
L["|cff0cd29dRight-click:|r |cffE0E0E0Enter Unlock Mode|r"] = "|cff0cd29d우클릭:|r |cffE0E0E0잠금 해제 모드 진입|r"
-- add Core Popup (본체 팝업)
L["Are you sure you want to reset ALL EUI addon settings to their defaults? This will reload your UI."] = "모든 EUI 애드온 설정을 기본값으로 초기화하시겠습니까? UI가 다시 불러와집니다."
L["Better Character Panel conflicts with the EllesmereUI's Character Sheet. Disable either Better Character Panel or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Better Character Panel 은 EllesmereUI 캐릭터 시트와 충돌합니다. 블리자드 UI 강화 설정에서 Better Character Panel 또는 캐릭터 시트 모양 변경 중 하나를 비활성화하세요."
L["Blizzard's Edit Mode snapping may not work correctly until you reload your UI."] = "기본 UI 편집 모드 맞춤이 UI 리로드 전까지 정상 동작하지 않을 수 있습니다."
L["Changing cursor anchor requires a UI reload to take effect."] = "커서 기준점 변경은 UI 리로드 후 적용됩니다."
L["Changing the frame source requires a UI reload to take effect."] = "프레임 출처를 변경하면 적용을 위해 UI 다시 로드가 필요합니다."
L["Changing the language requires a UI reload."] = "언어를 변경하려면 UI 리로드가 필요합니다."
L["Chonky Character Sheet conflicts with the EllesmereUI's Character Sheet. Disable either Chonky or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Chonky Character Sheet 은 EllesmereUI 캐릭터 시트와 충돌합니다. 블리자드 UI 강화 설정에서 Chonky 또는 캐릭터 시트 모양 변경 중 하나를 비활성화하세요."
L["Combat text font changes require a logout to character select to take effect. This is a WoW engine limitation."] = "전투 글자 글꼴 변경은 캐릭터 선택 화면까지 로그아웃해야 적용됩니다. 이는 WoW 엔진의 제한입니다."
L["Deja Character Stats conflicts with the EllesmereUI's Character Sheet. Disable either Deja or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Deja Character Stats 은 EllesmereUI 캐릭터 시트와 충돌합니다. 블리자드 UI 강화 설정에서 Deja 또는 캐릭터 시트 모양 변경 중 하나를 비활성화하세요."
L["Enable & Reload"] = "활성화 후 리로드"
L["Enter a name for the new profile:"] = "새 프로필의 이름을 입력하세요:"
L["Include CDM Spell Layout?"] = "CDM 주문 배치를 포함할까요?"
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "선택한 전문화의 재사용 대기시간 관리자 주문 배치(어떤 주문이 어떤 바에 놓이는지)와 주문별 설정을 모두 포함합니다."
L["Leatrix Plus has chat and minimap features that conflict with EllesmereUI. Disable any chat or minimap related options within Leatrix Plus to stay compatible."] = "Leatrix Plus 의 채팅·미니맵 기능은 EllesmereUI 와 충돌합니다. 호환을 위해 Leatrix Plus 의 채팅·미니맵 관련 설정을 모두 끄세요."
L["Many of ElvUI's modules are incompatible with EllesmereUI. Make sure to disable any conflicting modules."] = "ElvUI 의 여러 추가기능은 EllesmereUI 와 호환되지 않습니다. 충돌하는 여러 추가기능을 반드시 비활성화하세요."
L["Reset All & Reload"] = "모두 초기화 후 리로드"
L["Save & Exit"] = "저장 후 나가기"
L["TellMeWhen overlaps with EllesmereUI's core positional architecture. If you ONLY use for sound alerts it should be okay but may still cause issues."] = "TellMeWhen 은 EllesmereUI 의 핵심 위치 구조와 겹칩니다. 소리 알림 용도로만 쓰면 대체로 괜찮지만 여전히 문제가 생길 수 있습니다."
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "어두운 모드가 활성화되었을 때 바에 사용할 단색 채우기 색상입니다 (유닛 프레임, 공격대 프레임, 자원 바)."
L["This frame's source changes require a UI reload to take effect."] = "이 프레임의 출처 변경은 적용을 위해 UI 다시 로드가 필요합니다."
L["UI scale set to 0.5333. A reload is recommended."] = "UI 배율이 0.5333 으로 설정되었습니다. 리로드를 권장합니다."
L["You have unsaved position changes.\nWhat would you like to do?"] = "저장되지 않은 위치 변경이 있습니다.\n어떻게 하시겠습니까?"
-- add Core Format (본체 포맷)
L["%1$s Module"] = "추가기능 %1$s"
L["A profile named \"%1$s\" already exists. Please choose a different name."] = "\"%1$s\" 이름의 프로필이 이미 존재합니다. 다른 이름을 선택하세요."
L["Anchor to %1$s"] = "%1$s에 고정"
L["Are you sure you want to %1$s %2$s?"] = "정말 %2$s을(를) %1$s하시겠습니까?"
L["Are you sure you want to reset all %1$s settings to their defaults? This will reload your UI."] = "정말 %1$s 설정을 모두 기본값으로 초기화하시겠습니까? UI가 다시 로드됩니다."
L["Are you sure you want to reset all %s settings to their defaults? This will reload your UI."] = "%s의 모든 설정을 기본값으로 초기화하시겠습니까? UI가 다시 불러와집니다."
L["Elements cannot be anchored to\n%s"] = "기준점으로 사용할 수 없는 요소입니다:\n%s"
L["Export will include %1$s of %2$s addons."] = "내보내기에 %2$s개 중 %1$s개의 애드온이 포함됩니다."
L["Import will include %1$s of %2$s addons."] = "가져오기에 %2$s개 중 %1$s개의 애드온이 포함됩니다."
L["Importing %1$s"] = "%1$s 가져오는 중"
L["Keybind: %1$s"] = "단축키: %1$s"
L["Linked by Anchor/Width/Height Matching to: %1$s. These export together."] = "기준점/너비/높이 맞춤으로 연결됨: %1$s. 함께 내보내집니다."
L["Linked by Anchor/Width/Height Matching to: %1$s. These import together."] = "기준점/너비/높이 맞춤으로 연결됨: %1$s. 함께 가져와집니다."
L["Resolution Issue: Profile was made at %1$dx%2$d, yours is %3$dx%4$d"] = "해상도 문제: 프로필은 %1$dx%2$d에서 제작됨, 현재는 %3$dx%4$d입니다"
L["Select which specs you want %1$s to be assigned to"] = "%1$s에 할당할 전문화를 선택하세요"
L["Snap Target: %1$s"] = "스냅 대상: %1$s"
L["Snap to: %1$s"] = "스냅 위치: %1$s"
L["'%s' is now customized for %s."] = "'%s' 이(가) %s 에 맞게 사용자 지정되었습니다."
L["After anchoring, drag to an edge and choose a grow direction to maintain its corner spot as bars change size."] = "고정 후 가장자리로 끌어다 놓고 확장 방향을 고르면, 바 크기가 바뀌어도 모서리 자리를 유지합니다."
L["Assign this profile to the same specializations it was assigned to on export. Off = your current spec assignments stay as they are."] = "내보낼 때 지정돼 있던 전문화에 이 프로필을 그대로 지정합니다. 끄면 현재 전문화 지정이 유지됩니다."
L["Auto Assign to Specs"] = "전문화 자동 지정"
L["Beacon Reminders"] = "봉화 알림"
L["Clique controls click-casting on the same Raid Frames as EllesmereUI's HoverCast, so they conflict. Disable the Clique addon to use HoverCast."] = "Clique 가 EllesmereUI 의 HoverCast 와 같은 공격대 프레임에서 클릭 시전을 제어해 서로 충돌합니다. HoverCast 를 쓰려면 Clique 애드온을 꺼주세요."
L["Colors are shared globally from the \"%1$s\" profile.\nSwitch to it (or set Pull Colors From to this profile) to edit."] = "색상은 \"%1$s\" 프로필에서 전역 공유됩니다.\n편집하려면 그 프로필로 전환하거나, 색상 가져오기를 이 프로필로 지정하세요."
L["Coming Soon"] = "곧 추가 예정"
L["Conditional"] = "조건부"
L["Customizing Unlock Mode: %s (changes apply only to this group's specs)"] = "잠금 해제 모드 사용자 지정: %s (이 그룹의 전문화에만 적용)"
L["Export"] = "내보내기"
L["Export CDM Spells"] = "CDM 주문 내보내기"
L["Fallback"] = "대체"
L["Fallback Direction"] = "대체 방향"
L["Left-click to set a keybind.\nRight-click to unbind."] = "좌클릭: 단축키 지정\n우클릭: 해제"
L["No patch notes yet."] = "아직 패치 노트가 없습니다."
L["On"] = "켜짐"
L["Page"] = "페이지"
L["Section"] = "구역"
L["Paste Interrupted"] = "붙여넣기 중단됨"
L["Position and size settings are not synced and keep each profile's own values."] = "위치/크기 설정은 동기화되지 않고 프로필별 값을 유지합니다."
L["Processing"] = "처리 중"
L["The pasted string could not be read completely. Please paste it again."] = "붙여넣은 문자열을 끝까지 읽지 못했습니다. 다시 붙여넣어 주세요."
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "블리자드 CDM 에서 추적하는 주문 목록 자체는 바꿀 수 없습니다.\n여기서 고른 전문화는 블리자드 CDM 배치도 함께 공유하는 것을 권장합니다."
L["[ Import string captured (%1$s characters) ]"] = "[ 가져오기 문자열 캡처됨 (%1$s 자) ]"
L["no key set"] = "지정 안 됨"
L["MINI PATCH"] = "마이너 패치"
L["FIRST TIME SETUP"] = "최초 설정"
L["Open it anytime from the EUI Options Sidebar."] = "EUI 설정 사이드바에서 언제든 열 수 있습니다."
L["NEW SYSTEM"] = "새 시스템"
L["Link copied - paste it into your browser"] = "링크 복사됨 - 브라우저에 붙여넣으세요"
-- 2026-07-20 신규
L["Always show less common settings instead of collapsing them behind a Show Less Common link."] = "덜 쓰는 설정을 접어 두지 않고 항상 펼쳐서 보여 줍니다."
L["Auto Expand Less Common Settings"] = "덜 쓰는 설정 자동 펼치기"
