L["Include your Blizz UI Enhanced settings from the Window Skins and Tooltips, Menus & Popups tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "창 스킨과 툴팁, 메뉴 및 팝업 탭의 Blizz UI 향상 설정을 포함합니다. 이 설정은 계정 전체에 적용되며, 가져오는 사람이 선택하면 그 사용자의 모든 프로필 설정을 덮어씁니다."
