L["Blizzard's aura borders on the buffs, debuffs and weapon enchants, with every EllesmereUI bar feature."] = "모든 EllesmereUI 바 기능이 포함되어 있으며, 강화 효과, 약화 효과 및 무기 마법부여에 블리자드 스타일의 오라 테두리가 적용됩니다."
