L["Only show debuffs whose full duration is at most this many seconds. Combines with the filters; Unlimited applies no cap."] = "전체 지속 시간이 이 초 이하인 디바이스만 표시합니다. 필터와 결합됩니다: '제한 없음'은 상한선을 두지 않습니다."

--핵심 애드온 - 행동단축바
L["Skyriding (Airborne)"] = "하늘 경주 (비행 중)"
L["Skyriding Mount"] = "하늘 경주 탈것"
L["Mounted"] = "탈것 탑승 중"
L["Enemy Target"] = "적 대상"

--핵심 애드온 - 행동단축바 - 툴팁
L["While you are inside a house or plot."] = "집이나 개인 영지 내부에 있을 때 적용됩니다."
L["A target you can attack."] = "공격 가능한 대상입니다."
L["Hide while this condition is true"] = "이 조건이 참일 때 숨기기"
L["Reveal on hover only. Combines with the conditions below: hover-reveals while they all pass, stays hidden while any fails."] = "마우스를 올렸을 때만 표시합니다. 아래 조건들과 결합되어 작동합니다. 조건을 '모두 만족'하면 마우스 오버 시 표시되고, 하나라도 만족하지 못하면 숨겨진 상태를 유지합니다."
L["Only while AIRBORNE on a glide-capable mount or flight form. For the mount itself, ground included, use Skyriding Mount."] = "활공 가능한 탈것이나 비행 형태를 타고 '공중에 떠 있는' 동안에만 적용됩니다. 지상을 포함하여 탈것 자체를 조건으로 지정하려면 '하늘 경주 탈것'을 사용하세요."
L["While on a glide-capable mount, ground included, where Blizzard shows its vigor HUD. Skyriding (Airborne) additionally requires you to be flying."] = "블리자드 기본 UI에 기력 바가 표시되는 활공 가능한 탈것에 탑승한 상태(지상 포함)에 적용됩니다. '하늘 경주 (비행 중)' 조건은 여기에 추가로 실제 비행 중이어야 합니다."
L["Dungeons, raids, scenarios, arenas and battlegrounds. Garrisons do not count."] = "던전, 공격대, 시나리오, 투기장 및 전장입니다. 주둔지는 포함되지 않습니다."
L["Druid travel, aquatic and flight forms count as mounted."] = "드루이드의 여행, 바다, 비행 형태도 탈것 탑승 상태로 간주합니다."
L["Five-player dungeons, Mythic+ included. Delves, raids and scenarios do not count."] = "5인 던전입니다(신화+ 포함). 구렁, 공격대, 시나리오는 포함되지 않습니다."
L["While Party Mode is active. Party Mode can start in combat (Bloodlust); secure elements such as action bars then keep their current visibility until combat ends."] = "파티 모드가 켜져 있는 동안 적용됩니다. 파티 모드는 전투 중에도(피의 욕망) 시작될 수 있으며, 이때 행동 단축바 같은 보안 요소는 전투가 끝날 때까지 지금 표시 상태를 유지합니다."
L["Border size in pixels; for a textured style this is the size of its edge art."] = "테두리 크기(픽셀)입니다. 텍스처 스타일에서는 테두리 그림의 크기입니다."

--핵심 애드온 - 이름표
L["Hide Border"] = "테두리 숨기기"

--핵심 애드온 - 지원 및 시전바
L["Not Skyriding (Airborne)"] = "하늘라이딩 중 아님 (공중 비행 중 아님)"
L["Countdown Text Color"] = "카운트다운 텍스트 색상"
L["Resting"] = "휴식 중"
L["In Vehicle"] = "탈것 탑승 중"
L["While seated in a vehicle."] = "탈것에 탑승해 있는 동안."
L["While resting, in a city or at an inn."] = "대도시나 여관 등에서 휴식 중인 동안."

--핵심 애드온 - 지원 및 시전바 - 툴팁
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "이 요소는 '표시' 조건 중 하나만 일치해도 즉시 표시됩니다. '숨기기'는 두 일치 모드 모두에서 원래의 의미를 유지합니다. '숨기기'에 체크되어 있으면 모든 행에서 항상 숨겨집니다."
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "하늘라이딩(공중 비행)의 정반대 조건: 활강 가능한 탈것이나 비행 변신 상태로 공중에 떠 있지 않은 모든 상태(지상에 서 있는 상태 포함)를 의미합니다."

--핵심 애드온 - 유닛 프레임 
L["Hide Trailing Zeros"] = "소수점 끝의 0 숨기기"
L["Frame Source & Visibility"] = "프레임 출처 및 표시 여부"
L["Show When Health Missing"] = "생명력이 줄었을 때 표시"
L["Shows the frame while this unit is below full health; while enabled, a frame hidden by its visibility setting can still be clicked."] = "이 유닛의 생명력이 가득 차 있지 않으면 프레임을 표시합니다. 켜 두면 표시 여부 설정으로 숨겨진 프레임도 클릭할 수 있습니다."
L["Change health visibility out of combat"] = "전투 밖에서 변경 가능"
L["the Frame Source to be EllesmereUI"] = "프레임 출처 EllesmereUI"
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "이 프레임의 현재 설정을 덮어씁니다. 프레임 위치, 표시 여부, 사용 여부는 바뀌지 않습니다."
L["Dark Mode drives a Dark Mode override condition and can't be changed while editing an override"] = "어두운 모드는 어두운 모드 덮어쓰기 조건을 정하는 값이라, 덮어쓰기를 편집하는 동안에는 바꿀 수 없습니다"
L["Apply Border Size to all Frames"] = "테두리 크기 모든 프레임에 적용"
L["Focus Tracked Auras"] = "주시 추적 오라"
L["Boss Tracked Auras"] = "우두머리 추적 오라"
L["Tracked Auras"] = "추적 오라"
L["Included debuffs show in addition to your Debuff Filter selection (unless it is set to Only Tracked Auras)."] = "여기 넣은 약화 효과는 약화 효과 필터 선택과 별개로 추가로 표시됩니다('추적된 오라만'으로 설정한 경우는 제외)."
L["You are displaying NO debuffs at all."] = "약화 효과를 전혀 표시하지 않고 있습니다."
L["You are displaying NO buffs at all."] = "강화 효과를 전혀 표시하지 않고 있습니다."
L["Blizz Colored Target Header"] = "블리자드식 대상 이름 띠 색상"
L["Colors the strip behind the target's name by its reaction."] = "대상 이름 뒤의 띠를 대상의 반응(적대, 중립, 우호)에 따라 색칠합니다."
L["Custom Colors"] = "사용자 지정 색상"
L["Class Reactive"] = "직업 반응형"
L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "생명력 바를 한 가지 색 대신 남은 생명력에 따라 색칠합니다. '클래식'은 가득 찼을 때 초록에서 노랑을 거쳐 비었을 때 빨강이 됩니다. '사용자 지정 색상'은 이 줄의 세 색상 견본(가득 100%, 절반 50%, 없음 0%) 사이를 섞습니다. '직업 반응형'은 가득 찼을 때 직업 색상으로 시작해 피해를 받을수록 50%와 0% 색상으로 번집니다. '끔'이면 채우기 색상 견본이 그대로 쓰입니다. 어느 쪽이든 아래 그라데이션은 여기서 고른 색에서 시작해 계속 적용됩니다."
L["Level Text: Difficulty Color"] = "레벨 글자: 난이도 색상"
L["Colors level text by difficulty, from grey (trivial) through green, yellow and orange to red (5+ levels above you)."] = "레벨 글자를 난이도에 따라 회색(아주 쉬움)부터 초록, 노랑, 주황을 거쳐 빨강(나보다 5레벨 이상 높음)까지 색칠합니다."
L["Level Text: Include Friendly"] = "레벨 글자: 우호 대상 포함"
L["Friendly units get their level's color too, instead of gold."] = "우호 유닛도 금색 대신 레벨에 맞는 색을 씁니다."
L["Difficulty Color"] = "난이도 색상"
L["Colors an attackable unit's level by difficulty, as the default UI does."] = "기본 UI처럼 공격 가능한 유닛의 레벨을 난이도에 따라 색칠합니다."
L["This option does not apply to the player frame."] = "이 설정은 플레이어 프레임에는 적용되지 않습니다."
L["Power Border Options"] = "자원 바 테두리 설정"
L["Spell Cost Prediction"] = "주문 비용 예측"
L["While you cast, shows on the bar the mana the spell will cost."] = "시전하는 동안 그 주문이 소모할 마나를 바에 표시합니다."
L["Spell Cost Color"] = "주문 비용 색상"
L["Show spell cost preview"] = "주문 비용 미리보기 표시"
L["Hide spell cost preview"] = "주문 비용 미리보기 숨기기"
L["Apply Show Cast Bar and Cast Color to Target and Focus"] = "시전 바 표시와 시전 색상을 대상과 주시에 적용"
L["This option can't be used while Blizzard Class Resource Art is enabled in Resource Bars."] = "자원 바에서 '블리자드 직업 자원 아트'가 켜져 있으면 이 설정을 쓸 수 없습니다."
L["Buffs join the debuff stack as its first rows; debuffs continue on the next row and move as buff rows change."] = "강화 효과가 약화 효과 묶음의 첫 줄로 들어갑니다. 약화 효과는 다음 줄부터 이어지고, 강화 효과 줄 수가 바뀌면 함께 움직입니다."
L["This option is not available on the player frame"] = "플레이어 프레임에서는 쓸 수 없는 설정입니다"
L["This option requires Blizzard Style to be disabled"] = "이 설정을 사용하려면 블리자드 스타일을 꺼야 합니다"
