L["|cffff6060[EllesmereUI]|r A profile named \"%1$s\" already exists."] = "|cffff6060[EllesmereUI]|r \"%1$s\" 이름의 프로필이 이미 있습니다."
L["|cff00ff98EllesmereUI:|r Overrides intro reset. The announcement popup fires on your next /reload; the video guide fires on your next click of the overrides glyph."] = "|cff00ff98EllesmereUI:|r 재정의 소개를 초기화했습니다. 안내 팝업은 다음 /reload 때, 영상 가이드는 재정의 문양을 다음에 누를 때 다시 표시됩니다."
L["|cff00ff98EllesmereUI:|r Video guides and tutorial tips reset. Badges are back; one-time popups will fire again."] = "|cff00ff98EllesmereUI:|r 영상 가이드와 튜토리얼 팁을 초기화했습니다. 배지가 복원되고 1회성 팝업이 다시 표시됩니다."
L["|cffff6060[EllesmereUI]|r Spec changed: Unlock Mode closed, unsaved layout changes discarded."] = "|cffff6060[EllesmereUI]|r 전문화 변경: 잠금 해제 모드를 닫았습니다. 저장하지 않은 배치 변경은 사라졌습니다."
L["|cffff6060[EllesmereUI]|r Cannot enter Unlock Mode during combat."] = "|cffff6060[EllesmereUI]|r 전투 중에는 잠금 해제 모드에 들어갈 수 없습니다."
L["|cff00ff00[EllesmereUI]|r All hints reset. /reload to see them again."] = "|cff00ff00[EllesmereUI]|r 모든 힌트를 초기화했습니다. 다시 보려면 /reload 하세요."
L["|cff00ff00[EllesmereUI]|r UI scale reset. /reload to re-snapshot from your Blizzard scale."] = "|cff00ff00[EllesmereUI]|r UI 배율을 초기화했습니다. 블리자드 배율에서 다시 가져오려면 /reload 하세요."
L["|cffff6060[EllesmereUI]|r Cannot open options during combat. Use /eui to view Patch Notes."] = "|cffff6060[EllesmereUI]|r 전투 중에는 설정을 열 수 없습니다. 패치 노트는 /eui 로 볼 수 있습니다."
