L["This option requires a border style with divider art and a Border Size above 0."] = "이 옵션은 구분선 아트가 있는 테두리 모양과 0보다 큰 테두리 크기가 필요합니다."
L["This option requires a Circle or Pixels Circle Shape."] = "이 옵션은 원 또는 픽셀 원 모양이 필요합니다."
L["This option requires a Dispel Overlay, Color Custom Borders or Use Dispel Colors."] = "이 옵션은 해제 오버레이, 사용자 지정 테두리 색상 또는 해제 색상 사용이 필요합니다."
